5	//! # chili. Rust port of [Spice], a low-overhead parallelization library
6	//!
7	//! A crate for very low-overhead fork-join workloads that can potentially be
8	//! run in parallel.
9	//!
10	//! It works best in cases where there are many small computations and where it
11	//! is expensive to estimate how many are left on the current branch in order
12	//! to stop trying to share work across threads.
13	//!
14	//! [Spice]: https://github.com/judofyr/spice
15	//!
16	//! # Examples
17	//!
18	//! ```
19	//! # use chili::Scope;
20	//! struct Node {
21	//!     val: u64,
22	//!     left: Option<Box<Node>>,
23	//!     right: Option<Box<Node>>,
24	//! }
25	//!
26	//! impl Node {
27	//!     pub fn tree(layers: usize) -> Self {
28	//!         Self {
29	//!             val: 1,
30	//!             left: (layers != 1).then(|| Box::new(Self::tree(layers - 1))),
31	//!             right: (layers != 1).then(|| Box::new(Self::tree(layers - 1))),
32	//!         }
33	//!     }
34	//! }
35	//!
36	//! fn sum(node: &Node, scope: &mut Scope<'_>) -> u64 {
37	//!     let (left, right) = scope.join(
38	//!         |s| node.left.as_deref().map(|n| sum(n, s)).unwrap_or_default(),
39	//!         |s| node.right.as_deref().map(|n| sum(n, s)).unwrap_or_default(),
40	//!     );
41	//!
42	//!     node.val + left + right
43	//! }
44	//!
45	//! let tree = Node::tree(10);
46	//!
47	//! assert_eq!(sum(&tree, &mut Scope::global()), 1023);
48	//! ```
49	
