105	#[derive(Debug)]
106	struct Context {
107	    lock: Mutex<LockContext>,
108	    job_is_ready: Condvar,
109	    scope_created_from_thread_pool: Condvar,
110	}
111	
112	fn execute_worker(context: Arc<Context>, barrier: Arc<Barrier>) -> Option<()> {
113	    let mut first_run = true;
114	
115	    let mut job_queue = JobQueue::default();
116	    let mut scope = Scope::new_from_worker(context.clone(), &mut job_queue);
117	
118	    loop {
119	        let job = {
120	            let mut lock = context.lock.lock().unwrap();
121	            lock.pop_earliest_shared_job()
122	        };
123	
124	        if let Some(job) = job {
125	            // SAFETY:
126	            // Any `Job` that was shared between threads is waited upon before
127	            // the `JobStack` exits scope.
128	            unsafe {
129	                job.execute(&mut scope);
130	            }
131	        }
132	
133	        if first_run {
134	            first_run = false;
135	            barrier.wait();
136	        };
137	
138	        let lock = context.lock.lock().ok()?;
139	        if lock.is_stopping || context.job_is_ready.wait(lock).is_err() {
140	            break;
141	        }
142	    }
143	
144	    Some(())
145	}
146	
147	fn execute_heartbeat(
148	    context: Arc<Context>,
149	    heartbeat_interval: Duration,
150	    num_workers: usize,
151	) -> Option<()> {
152	    loop {
153	        let interval_between_workers = {
154	            let mut lock = context
155	                .scope_created_from_thread_pool
156	                .wait_while(context.lock.lock().ok()?, |l| {
157	                    l.heartbeats.len() == num_workers && !l.is_stopping
158	                })
159	                .ok()?;
160	
161	            if lock.is_stopping {
162	                break;
163	            }
164	
165	            let now = Instant::now();
166	            lock.heartbeats.retain(|_, h| {
167	                h.is_set
168	                    .upgrade()
169	                    .inspect(|is_set| {
170	                        if now.duration_since(h.last_heartbeat) >= heartbeat_interval {
171	                            is_set.store(true, Ordering::Relaxed);
172	                            h.last_heartbeat = now;
173	                        }
174	                    })
175	                    .is_some()
176	            });
177	
178	            heartbeat_interval.checked_div(lock.heartbeats.len() as u32)
179	        };
180	
181	        // If there are no heartbeats (`lock.heartbeats.len()` is 0), skip
182	        // immediately to the next iteration of the loop to trigger the wait.
183	        if let Some(interval_between_workers) = interval_between_workers {
184	            thread::sleep(interval_between_workers);
185	        }
186	    }
187	
188	    Some(())
189	}
