217	/// A `Scope`d object that you can run fork-join workloads on.
218	///
219	/// # Examples
220	///
221	/// ```
222	/// # use chili::ThreadPool;
223	/// let mut tp = ThreadPool::new();
224	/// let mut s = tp.scope();
225	///
226	/// let mut vals = [0; 2];
227	/// let (left, right) = vals.split_at_mut(1);
228	///
229	/// s.join(|_| left[0] = 1, |_| right[0] = 1);
230	///
231	/// assert_eq!(vals, [1; 2]);
232	/// ```
233	#[derive(Debug)]
234	pub struct Scope<'s> {
235	    context: Arc<Context>,
236	    job_queue: ThreadJobQueue<'s>,
237	    heartbeat: Arc<AtomicBool>,
238	    join_count: u8,
239	}
240	
241	impl<'s> Scope<'s> {
242	    /// Returns the global scope.
243	    ///
244	    /// # Examples
245	    ///
246	    /// ```
247	    /// # use chili::Scope;
248	    /// let _s = Scope::global();
249	    /// ```
250	    pub fn global() -> Scope<'static> {
251	        ThreadPool::global().scope()
252	    }
253	
254	    fn new_from_thread_pool(thread_pool: &'s ThreadPool) -> Self {
255	        let heartbeat = thread_pool.context.lock.lock().unwrap().new_heartbeat();
256	        thread_pool
257	            .context
258	            .scope_created_from_thread_pool
259	            .notify_one();
260	
261	        Self {
262	            context: thread_pool.context.clone(),
263	            job_queue: ThreadJobQueue::Current(JobQueue::default()),
264	            heartbeat,
265	            join_count: 0,
266	        }
267	    }
268	
269	    fn new_from_worker(context: Arc<Context>, job_queue: &'s mut JobQueue) -> Self {
270	        let heartbeat = context.lock.lock().unwrap().new_heartbeat();
271	
272	        Self {
273	            context,
274	            job_queue: ThreadJobQueue::Worker(job_queue),
275	            heartbeat,
276	            join_count: 0,
277	        }
278	    }
279	
280	    fn heartbeat_id(&self) -> usize {
281	        Arc::as_ptr(&self.heartbeat) as usize
282	    }
283	
284	    fn wait_for_sent_job<T: Send>(&mut self, receiver: Receiver<T>) -> Option<thread::Result<T>> {
285	        if self
286	            .context
287	            .lock
288	            .lock()
289	            .unwrap()
290	            .shared_jobs
291	            .remove(&self.heartbeat_id())
292	            .is_some()
293	        {
294	            return None;
295	        }
296	
297	        while receiver.is_empty() {
298	            let job = {
299	                let mut lock = self.context.lock.lock().unwrap();
300	                lock.pop_earliest_shared_job()
301	            };
302	
303	            if let Some(job) = job {
304	                // SAFETY:
305	                // Any `Job` that was shared between threads is waited upon
306	                // before the `JobStack` exits scope.
307	                unsafe {
308	                    job.execute(self);
309	                }
310	            } else {
311	                break;
312	            }
313	        }
314	
315	        Some(receiver.recv())
316	    }
317	
318	    #[cold]
319	    fn heartbeat(&mut self) {
320	        let mut lock = self.context.lock.lock().unwrap();
321	
322	        let time = lock.time;
323	        if let Entry::Vacant(e) = lock.shared_jobs.entry(self.heartbeat_id()) {
324	            if let Some(job) = self.job_queue.pop_front() {
325	                e.insert((time, job));
326	
327	                lock.time += 1;
328	                self.context.job_is_ready.notify_one();
329	            }
330	        }
331	
332	        self.heartbeat.store(false, Ordering::Relaxed);
333	    }
334	
335	    fn join_seq<A, B, RA, RB>(&mut self, a: A, b: B) -> (RA, RB)
336	    where
337	        A: FnOnce(&mut Scope<'_>) -> RA + Send,
338	        B: FnOnce(&mut Scope<'_>) -> RB + Send,
339	        RA: Send,
340	        RB: Send,
341	    {
342	        let rb = b(self);
343	        let ra = a(self);
344	
345	        (ra, rb)
346	    }
347	
348	    fn join_heartbeat<A, B, RA, RB>(&mut self, a: A, b: B) -> (RA, RB)
349	    where
350	        A: FnOnce(&mut Scope<'_>) -> RA + Send,
351	        B: FnOnce(&mut Scope<'_>) -> RB + Send,
352	        RA: Send,
353	        RB: Send,
354	    {
355	        let stack = JobStack::new(a);
356	        let job = Job::new(&stack);
357	
358	        // SAFETY:
359	        // `job` is alive until the end of this scope.
360	        unsafe { self.job_queue.push_back(&job) };
361	
362	        if self.heartbeat.load(Ordering::Relaxed) {
363	            self.heartbeat();
364	        }
365	
366	        let rb = b(self);
367	
368	        if let Some(receiver) = job.take_receiver() {
369	            let ra = match self.wait_for_sent_job(receiver) {
370	                Some(Ok(val)) => val,
371	                Some(Err(e)) => panic::resume_unwind(e),
372	                // SAFETY:
373	                // Since the `job` didn't have the chance to be actually
374	                // sent across threads, it cannot take the closure out of the
375	                // `JobStack` anymore. `JobStack::take_once` is thus called
376	                // only once.
377	                None => unsafe { (stack.take_once())(self) },
378	            };
379	
380	            (ra, rb)
381	        } else {
382	            self.job_queue.pop_back();
383	
384	            // SAFETY:
385	            // Since the `job` was popped from the back of the queue, it cannot
386	            // take the closure out of the `JobStack` anymore.
387	            // `JobStack::take_once` is thus called only once.
388	            (unsafe { (stack.take_once())(self) }, rb)
389	        }
390	    }
391	
392	    /// Runs `a` and `b` potentially in parallel on separate threads and
393	    /// returns the results.
394	    ///
395	    /// This variant skips checking for a heartbeat every 16 calls for improved
396	    /// performance.
397	    ///
398	    /// # Examples
399	    ///
400	    /// ```
401	    /// # use chili::Scope;
402	    /// let mut vals = [0; 2];
403	    /// let (left, right) = vals.split_at_mut(1);
404	    ///
405	    /// Scope::global().join(|_| left[0] = 1, |_| right[0] = 1);
406	    ///
407	    /// assert_eq!(vals, [1; 2]);
408	    /// ```
409	    pub fn join<A, B, RA, RB>(&mut self, a: A, b: B) -> (RA, RB)
410	    where
411	        A: FnOnce(&mut Scope<'_>) -> RA + Send,
412	        B: FnOnce(&mut Scope<'_>) -> RB + Send,
413	        RA: Send,
414	        RB: Send,
415	    {
416	        self.join_with_heartbeat_every::<64, _, _, _, _>(a, b)
417	    }
418	
419	    /// Runs `a` and `b` potentially in parallel on separate threads and
420	    /// returns the results.
421	    ///
422	    /// This variant skips checking for a heartbeat every `TIMES - 1` calls for
423	    /// improved performance.
424	    ///
425	    /// # Examples
426	    ///
427	    /// ```
428	    /// # use chili::Scope;
429	    ///
430	    /// let mut vals = [0; 2];
431	    /// let (left, right) = vals.split_at_mut(1);
432	    ///
433	    /// // Skip checking 7/8 calls to join_with_heartbeat_every.
434	    /// Scope::global().join_with_heartbeat_every::<8, _, _, _, _>(|_| left[0] = 1, |_| right[0] = 1);
435	    ///
436	    /// assert_eq!(vals, [1; 2]);
437	    /// ```
438	    pub fn join_with_heartbeat_every<const TIMES: u8, A, B, RA, RB>(
439	        &mut self,
440	        a: A,
441	        b: B,
442	    ) -> (RA, RB)
443	    where
444	        A: FnOnce(&mut Scope<'_>) -> RA + Send,
445	        B: FnOnce(&mut Scope<'_>) -> RB + Send,
446	        RA: Send,
447	        RB: Send,
448	    {
449	        self.join_count = self.join_count.wrapping_add(1) % TIMES;
450	
451	        if self.join_count == 0 || self.job_queue.len() < 3 {
452	            self.join_heartbeat(a, b)
453	        } else {
454	            self.join_seq(a, b)
455	        }
456	    }
457	}
