615	impl Drop for ThreadPool {
616	    fn drop(&mut self) {
617	        self.context
618	            .lock
619	            .lock()
620	            .expect("locking failed")
621	            .is_stopping = true;
622	        self.context.job_is_ready.notify_all();
623	        self.context.scope_created_from_thread_pool.notify_one();
624	
625	        for handle in self.worker_handles.drain(..) {
626	            handle.join().unwrap();
627	        }
628	
629	        if let Some(handle) = self.heartbeat_handle.take() {
630	            handle.join().unwrap();
631	        }
632	    }
633	}
