692	    #[test]
693	    fn join_very_long() {
694	        let threat_pool = ThreadPool::new();
695	
696	        fn increment(s: &mut Scope, slice: &mut [u32]) {
697	            match slice.len() {
698	                0 => (),
699	                1 => slice[0] += 1,
700	                _ => {
701	                    let mid = slice.len() / 2;
702	                    let (left, right) = slice.split_at_mut(mid);
